```python
import heapq

def solve(n, stations, x):
    # create graph with start node having infinite distance (since it's the source)
    graph = {}
    inf = float('inf')
    for i in range(1, x+1):
        graph[i] = {i: 0} if i in stations else {i: inf}

    # create empty priority queue and add start node with distance as 0
    queue = [(0, 0)]

    while queue:
        current_distance, current_node = heapq.heappop(queue)

        if current_node == x:
            return current_distance  # reached destination

        for neighbor, cost in graph[current_node].items():
            new_distance = current_distance + cost
            if new_distance < graph[neighbor].get(neighbor, inf):
                graph[neighbor][neighbor] = new_distance  # update distance to self
                heapq.heappush(queue, (new_distance, neighbor))
                if neighbor in stations:  # refuel at gas station
                    graph[neighbor][current_node] = 0  # cost of travel from gas station back to current node is 0

    return -1  # unreachable destination

# test cases
num_tests = int(input())
for _ in range(num_tests):
    n, x = map(int, input().split())
    stations = list(map(int, input().split()))[1:]  # remove the first element (n)
    print(solve(n, sorted(stations), x))
```

