def euler(n):
    if n <= 2:
        return n % 3 == 0

    powers = list(accumulate([2, 3], lambda a, b: a * b))

    for power in reversed(powers):
        if n < power:
            break

        divisor = n // power
        remainder = n % power

        if remainder == 0:
            return True

        n -= power - remainder

