import math

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous = {node: None for node in graph}
    unvisited = set(graph)

    while unvisited:
        current_node = min(unvisited, key=lambda x: distances.get(x, float('inf')))
        unvisited.remove(current_node)

        for neighbor, weight in graph[current_node].items():
            new_distance = distances[current_node] + weight
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                previous[neighbor] = current_node

    return distances, previous

def solve(points):
    n = len(points) // 2
    graph = {point: {} for point in set(points)}

    for i in range(n):
        x1, y1 = points[i * 2], points[i * 2 + 1]
        for j in range(1, n + 1):
            if i == j:
                continue  # don't add a self-edge
            x2, y2 = points[j * 2], points[j * 2 + 1]
            graph[(x1, y1)][(x2, y2)] = math.hypot(abs(x1 - x2), abs(y1 - y2))

    distances, _ = dijkstra(graph, start=(min(points)[0], min(points)[1]))
    minimum_path_length = distances[max(points, key=lambda point: points[1] if (point in distances) else float('inf'))][1]

    path_coords = [previous[(min(points), min(points)[1])]]
