import sys
from heapq import heappush, heappop

def solve(x, y, k):
    # Define Monocarp's state as a tuple: [current position, direction (-1 for left, 1 for right, 0 if not moving), time spent carrying the chest, whether he has the key]
    state = (0, 0, 0, False)
    actions, costs = [[(x, 0, 0, True), 0], [(y, 0, 0, False), 0]]

    # Use a priorities-queue to find the next best move
    heappush((actions, costs), state)

    while heappop(actions)[1] < k:
        curr_pos, direction, time_spent, has_key = heappop(actions)[0]
        new_time = time_spent + curr_pos if direction != 0 else time_spent
        if curr_pos == y and not has_key:
            heappush(actions, (curr_pos, -direction, new_time, True))
        elif curr_pos == x and has_key:
            heappush(actions, (curr_pos, 0, new_time, True))
        else:
            if direction > 0:
                heappush(actions, ((curr_pos + 1), -direction, new_time, False))
            elif direction < 0:
                heappush(actions, ((curr_pos - 1), -direction, new_time, False))
            else:
                heap = sorted([(pos, direction, time) for (pos, dir, _, _) in actions], key=lambda x: x[2])
                next_move = heap.pop()[0]
                if next_move[1] > 0:
                    heappush(actions, ((next_move[0] + curr_pos), -next_move[1], new_time, False))
                elif next_move[1] < 0:
                    heappush(actions, ((next_move[0] + curr_pos), -next_move[1], new_time, False))

    # Return the minimum time required to open the chest
    return heappop(actions)[2] if len(actions) > 0 else -1

if __name__ == "__main__":
    for _ in range(int(sys.stdin.readline())):
        x, y, k = map(int, sys.stdin.readline().strip().split(" "))
        print(solve(x, y, k))
