import functools
from itertools import accumulate

def sorting_with_twos(arr):
    # Compute cumulative sum of the array and reverse it.
    # The result will be non-increasing order with all elements >= 0.
    cumsum = list(accumulate(reversed(arr), initial = 0))[::-1]

    @functools.lru_cache(maxsize=None)
    def helper(index, mask):
        if index == len(cumsum):
            return True

        if mask & (1 << cumsum[index]) != 0:
            # The element at the index was already processed during a previous operation. We ignore it this time.
            return helper(index + 1, mask)

        # Perform an operation to set the bit for the current element at the index.
        new_mask = mask | (1 << cumsum[index])
        return helper(index + 1, new_mask) or helper(index + 2 ** next((j for j in range(index + 1, len(cumsum)) if cumsum[j] - cumsum[index] == 1), None), new_mask)

    return helper(0, 0)

def main():
    t = int(input().strip())
    for _ in range(t):
        n = int(input().strip())
        a = list(map(int, input().split()))
        print('YES' if sorting_with_twos(a) else 'NO')

if __name__ == "__main__":
    main()
```

