import sys

def solve(n, s, m, t):
    # Base case: empty string is always good
    if n == 0:
        return True

    # If the last character of the current string is equal to the first character of the template, we can eliminate one of them and recurse for the shorter string.
    if s[n - 1] == t[m - 1]:
        return solve(n - 1, s[:n-1], m - 1, t[:m-1])

    # If not, we try to recursively insert the template at all possible positions in the current string.
    for i in range(1, n):
        if not solve(i, s[:i], m, t) and not solve(n - i - 1, s[i:], m, t):
            # If after removing the current character from the input string and finding it impossible to make it good, we return False.
            return False
    return True

if __name__ == "__main__":
    T = int(sys.stdin.readline())
    for _ in range(T):
        n, m = map(int, sys.stdin.readline().split())
        s = sys.stdin.readline()
        t = sys.stdin.readline()
        if solve(n, s, m, t):
            print("YES")
        else:
            print("NO")
