import math

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            factors.append(i)
            n //= i
    if n > 1:
        factors.append(n)
    return factors

def solve(n):
    prime_factors_set = set(prime_factors(n))
    three_in_set = 3 in prime_factors_set
    for triplet in combinations(range(1, int(math.sqrt(n))), 3):
