from collections import defaultdict

def sieve_of_eratosthenes(n):
    primes = [True] * (n+1)
    primes[0], primes[1] = False, False
    for p in range(2, int(n**0.5)+1):
        if primes[p]:
            for i in range(p*p, n+1, p):
                primes[i] = False
    return primes

def solve():
    primes = sieve_of_eratosthenes(100_001)
    three_multiples = set([3*i for i in range(1, 1+len(primes)) if primes[i]])
    result = defaultdict(list)
    for n in range(1, 100_001):
        if n not in three_multiples:
            xyz = []
            for p in primes[:n]:
                if p > (n-p)**0.5:
                    break
                rem = (n - p) % p
                if rem == 0 or rem == p - p:
                    continue
                xyz += [(p, rem)]
            for x in xyz:
                y, z = x[0], n - x[1]
                if (y, z) not in result and y*y + z*z <= n:
                    result[(n - y - z, y, z)] = True
    for k, v in sorted(result.items(), key=lambda item: item[0], reverse=True):
        print("YES")
        print(*k)

test_cases = int(input())
for _ in range(test_cases):
    n = int(input())
    solve()
