    # BFS to find the shortest path on the device layout
    visited = set()
    visited.add((device[0], 0))
    queue = deque((device[0], 0, 0))

    while queue:
        current_pin, _position, _time_taken = queue.popleft()

        for next_digit in layout[current_pin]:
            if (next_digit, _position) not in visited:
                visited.add((next_digit, _position))
                queue.append((next_digit, _position + 1, _time_taken + 1))

    # Find the digit at last position from the start of pin code (backward traversal)
    actual_pin = []
    for pos, num in enumerate(reversed(visited)):
        actual_pin.append(num[0])

    return len(actual_pin)

