                goals_scored[i] += 1
                goals_scored[j] -= 1
            else:
                goals_scored[j] += 1
                goals_scored[i] -= 1

    # The efficiency of the missing team is the total number of goals it scored minus the total number of goals it conceded
    # We're assuming that the order of goals in the pairs does not matter, so we take absolute value to avoid negative numbers
    return sum(abs(g) for g in goals_scored) - reduce(lambda x, y: x + y, goals_scored, 0)
