import sys
import heapq
from collections import defaultdict

def dijkstra(G, src):
    inf = float('inf')
    dist = {src: 0}
    q = list(G)[1:] + [src]
    hq = [(0, src)]

    while q:
        d, u = heapq.heappop(hq)

        for v, (w, edge) in enumerate(list(G[u])):
            if w > 0 and v not in dist:
                t = dist[u] + edge
                if t < dist.get(v, inf):
                    dist[v] = t
                    heapq.heappush(hq, (t, v))

    return dist

def mx_array(n, k, x):
    G = defaultdict(lambda: [])
    for i in range(0, n - 1):
        for j in range(i + 1, n):
            a, b = (i, j) if i < k else (j, i)
            wt = min((k - max(a, b)) // (a - b), x)
            G[a][b] = G[b][a] = [wt + 1, (a, b)]
    MEX, dist = dijkstra({0}, [k]) - {0: 0}
    return sum(dist.values()) if MEX <= k else -1

