from typing import List

@functools.lru_cache(maxsize=None)
def mex(arr: List[int]) -> int:
    data = Counter(arr)
    result, count = 0, len(arr)
    for key in data:
        count -= data[key]
        if count == 0:
            return key
        result = key + result
    return result

def solve(n: int, k: int, x: int) -> int:
    if n == 1:
        return min(x, k)

    max_sum = 0
    for i in range(min(k, x) + 1, 0, -1):
        r = n // (i - 1)  # How many groups of (i-1) elements we need. Each group sum should be equal to k - (i-1).
        if (r * (k - i + 1)) <= n:  # Check if number of groups and the size of each group are valid considering n is given.
            gap = k - r * (k - i + 1)  # The remaining value to fill the last group.
            sub_sum = (r * (k - i + 1)) + gap if gap else r * (k - i + 1)
            current_sum = max(sub_sum, 0) * i
            max_sum = max(max_sum, current_sum)

    return max_sum or -1

