            elif player == 1 and button > a + b or player == 2 and button <= a + b:
                taken_by_other |= dp(3 - player, buttons.copy())
        return taken_by_other

    for player in range(1, 4):
        if dp(player, {i: True for i in range(1, a + b + c + 1)}):
            return "Second"
    return "First"

