from collections import defaultdict, deque

def bfs(g, v, height):
    queue = deque([v])
    visited = set([v])
    step_levels = defaultdict(set)

    while queue:
        curr = queue.popleft()
        for neighbor in (g[curr] - visited):
            # if the difference between current and neighbor's level is equal to k, then it's a valid pair
            if (height - step_levels[neighbor]) == height - k:
                yield curr
                visited.add(neighbor)
                step_levels[neighbor].add(step_levels[curr] + 1)
            # if the difference is greater than k, it means that this neighbor belongs to a higher level
            elif (height - step_ levels[neighbor]) > height - k:
                step_levels[neighbor].add(step_levels[curr] + 1)
            # otherwise, this neighbor belongs to a lower level, we add it to the queue for later exploration
            else:
                queue.append(neighbor)
                visited.add(neighbor)
                step_levels[neighbor].add(step_levels[curr])
    return list(visited)

def solve():
