        @lru_cache((len(a),) + (1 << n,))
        def dfs(cur, curr_sum):
            if cur == 0 or curr_sum < -1e9:
                return -1e9
            if dp[cur % 2][cur] != -1:
                return dp[cur % 2][cur]
            res = curr_sum
            for mask, bit in enumerate(range(n-1, -1, -1)):
