import math
from heapq import heappush, heappop

def dijkstra(grid, start, end):
    queue = [(0, start)]
    visited = set()
    visited.add(start)

    while queue:
        _, current = heappop(queue)

        if current == end:
            return current

        neighbours = []
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            x, y = current[0] + dx, current[1] + dy
            if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] not in visited:
                neighbours.append((grid[x][y], (x, y)))

        for neighbour, cost in sorted(neighbours, key=lambda x: x[0]):
            heappush(queue, (current[0] + cost, neighbour))
            visited.add(neighbour)

    return -1

def shortest_path(a, b):
    grid = [[math.inf]*len(str(b)) for _ in range(len(str(a)))]
    grid[0][0] = 0

    steps = dijkstra(grid, (0, 0), (a-1, b-1))
    if steps > 2:
        return 1, (0, 0), (a-1, b-1)

    grid[0][0] = math.inf
    steps2 = dijkstra(grid, (a-1, b-1), (0, 0))
    if steps + steps2 <= 3:
        return 2, (steps, (0, 0)), ((steps, (a-1, b-1)), (steps2, (0, 0)))

    grid[0][0] = math.inf
    grid[(a-1)//2][(b-1)//2] = 0
    steps3 = dijkstra(grid, (0, 0), (a-1, b-1))
    ifsteps + steps3 <= 3:
        return 3, (steps, (0, 0)), ((steps, (a-1, b-1)), (steps3, (int((a - 1) / 2), int((b - 1) / 2))), ((steps * 2, (int((a + a % 2) / 2), int((b + b % 2) / 2))))

    return 1, (0, 0), (a-1, b-1)

def main():
    for _ in range(int(input())):
        ab = list(map(int, input().split()))
        _, n_jumps, path = shortest_path(*ab)
        print(n_jumps)
        coords = []
        for jump in path:
            coords.append(jump)
        print(*coords)

if __name__ == "__main__":
    main()
