def solve(a, b):
    # Calculate the distance between Ian and Mary
    dist = math.sqrt(a**2 + b**2)

    # If the distance is 1 or less, only one jump is needed
    if dist <= 2:
        return 1, (0, 0), (dist, 0), (a, b)

    # Create a list of potential jumps for Ian
    potential_jumps = []
    for i in range(1, int(dist) + 1):
        # Calculate the x-coordinate of the midpoint of the jump
        mx = dist - (i * (dist - i)) / 2

        # Ensure that both the x and y coordinates are integers
        if mx.is_integer() and math.sqrt(i**2 + (mx - a)**2) <= 2:
            potential_jumps.append((i, int(mx)))

    # Sort the list of potential jumps by first coordinate (jump length)
    bisect.insort_left(potential_jumps, (float("inf"), None))

    # Loop through the potential jumps, simulating Ian's moves using two jumps
    for i in range(len(potential_jumps) - 1, -1 ,-1):
        jump = potential_jumps[i]

        # Check if the second jump can bring Ian to Mary after the first jump
        y_new = jump[1] - a + b
        if y_new.is_integer() and math.sqrt((jump[0])**2 + (y_new - b)**2) <= 2:
