def mod_inverse(a, m):
    p = m
    u1 = 1
    u2 = 0

    while a > 1:
        q = a // p
        u1, u2 = u2, (u1 - q * u2) % m
        a, p = p % a, p % m

    return u1 % m

def solve(n, k):
