        return "YES" if n % 2 == 0 else "NO"
    if k >= n:
        return "NO"
    coins = defaultdict(int)

    for x in range(1, min(n, k) + 1):
        coins[x * k] += 1
    while True:
        change = 0
        for coin in sorted(coins.keys()):
            if change + coin <= n:
                change += coin
            else:
                break
        if change == n:
            return "YES"
        inv_k = mod_inverse(k, n - change)
        for coin in sorted(coins.keys(), reverse=True):
            new_coin = (coin * inv_k) % n
            if new_coin not in coins or coins[new_coin] == 0:
                break
            change += min(coins[new_coin], coin)
            coins[new_coin] -= min(coins[new_coin], coin)
        else:
            return "NO"

