    return count % 2 == 0

def find_and_replace(s):
    possibles = ["0", "1"]

    for c in s:
        if not (c in possibles):
            return False

    def replace(char, replaced_by):
        return "".join([re.sub(f"{char}", replaced_by, s)])

    if alternating_binary(s):
        return True

    # Iterate through each character and change it to 0/1 to create an alternating string
    for c in s:
        for repl in possibles:
            new_s = replace(c, repl)
            if alternating_binary(new_s):
                return True

    return False

