def dijkstra(grid, start, end):
    # Calculate the distances from the start node to each cell in the grid.
    distance_map = {start: 0}
    unvisited = collections.deque([start])

    while unvisited:
        current = unvisited.popleft()

        for dx, dy in [(1, 1), (1, 0)]:
