import sys
from collections import deque

def solve(n: int, a: list) -> tuple[list, list]:
    q = deque()
    max_stack, min_stack, res = [], [], [0] * n

    for i, val in enumerate(a):
        if val > 0:
            while q and q[-1][-2] <= -val:
                q.pop()
            if q:
                max_stack.append(q[-1][0])
            q.append((i, val))

    for v in q:
        max_stack.append(v[0])

    q = deque()
    for i, val in enumerate(reversed(a)):
        if val > 0:
            while q and q[-1][-2] >= -val:
                q.pop()
            if q:
                min_stack.append(q[-1][0])
            q.append((n - i - 1, val))

    for v in reversed(q):
        min_stack.append(v[0])

    for i, (max_elem, min_elem) in enumerate(zip(max_stack, min_stack)):
        res[i] = max_elem - min_elem

    return res

if __name__ == "__main__":
    for _ in range(int(sys.argv[1])):
        n = int(input())
        a = list(map(int, input().split()))
        print(*solve(n, a))
