import sys
import functools

def max_equal(a, b):
    # Check if a[n] and b[n] can be equal to the maximum of both arrays after swapping some elements.
    @functools.lru_cache(maxsize=None)
    def dfs(i, _a, _b):
        # Base case: no more elements left to swap
        if i == len(_a):
            return (_a[-1] >= max(_b)) and (b[-1] >= max(_a))

        # Recursive case: consider swapping a[i] with b[i], or not considering this swap.
        return dfs(i+1, _a[i:] + [_b[i]], _b[i:] + [_a[i]]) or \
               dfs(i+1, _a[i:], _b[i:]) or \
               dfs(i+1, [b[i]] + _a[i:], [a[i]] + _b[i:])

    return dfs(0, a, b)

