    x1, y1, x2, y2 = map(int, sys.stdin.readline().split())
    graph = [[] for _ in range(n * m)]

    for i in range(n):
        for j in range(m):
            next_row = (i + 1) % n
            next_col = (j + 1) % m
            if i < n - 1 and j >= 1:
                graph[i * m + j].append((i * m + j + 1, 1))
                graph[(next_row * m + j - 1)].append((i * m + j, 1))
            if i >= 1 and j < m - 1:
                graph[i * m + j].append((i * m + j + m, 1))
                graph[(i * m + j - 1)].append((next_row * m + j, 1))
            if i < n - 1 and j < m - 1:
                graph[i * m + j].append(((next_row * m + next_col), 1))
                graph[(i * m + j - m)].append((next_row * m + j, 1))
                graph[(i * m + j + 1)].append((i * m + next_col, 1))
                graph[(next_row * m + j)].append((i * m + next_col, 1))

    parent = [-1] * (n * m)
    size = [0] * (n * m + 1)

    d = DefaultDict(int)

    def dfs(cur):
        if cur in d:
            return d[cur]

        p = find(cur)
        d[cur] = p
        for nei, _ in graph[cur]:
            d[cur] = min(d[cur], 1 + dfs(nei))
        return d[cur]

    def bfs():
        h = []
        uf = list(enumerate((x1, y1)))
        heappush(h, (0, x1 * m + y1))
        while h:
            dist, cur = heappop(h)
            p = find(cur)
            if p == find(x2 * m + y2):
                return dist - 1
            d[cur] = dist
            for nei, _ in graph[cur]:
                if d[nei] == None:
                    heappush(h, (dist + 1, nei))
                    uf.append((nei, dist + 1))
        return -1

    result = bfs()

    if result < 0:
        for i in range(n):
            for j in range(m):
                x, y = i * m + j
                if parent[x] != -1 and find(x) == find(find(x1 * m + y1)):
                    size[find(find(x1 * m + y1))] -= 1
                    if size[find(find(x1 * m + y1))] < 0:
                        parent[x] = -2
                result += 1
        result +=dfs(find(find(x1 * m + y1)))

    print(result)

