        # Radix Sort based on lengths
        for len_val in sorted(set(len(e) for e in strings)):
            pxtree[len_val].sort()
            for i, s in pxtree[len_val]:
                if pfx:
                    k = ord(s[-1]) - ord(strings[pfx[ord(s[-1])]-1][-1]) + 26
                    if k < len_val or pfx[k] == i or (pfx[k] > 0 and strings[pfx[k]-1][-1] != s[-1]):
                        pxf[len_val].add(i)
