```python
import itertools, sys

def dfs(remaining, total, subtotal, candidates):
    if remaining == 0:
        yield from ((subtotal, ) * (total // subtotal))
        return

    for c in candidates[remaining]:
        if c > subtotal + total % subtotal:
            break
        nxt = dfs(remaining - 1, total, subtotal + c, candidates)
        for num in nxt:
            yield num

def solve(n, s, r):
    candidates = [range(1, 7)] * n
    total_sum = sum(candidates[i] for i in range(len(candidates)))
    for c in candidates[:r]:
        total_sum -= c

    if total_sum == r:
        yield from map(" ".join, dfs(len(candidates) - 1, s, max(candidates), candidates))
    elif total_sum > r:
        yield from map(" ".join, dfs(0, s, 6, ([6] + candidates)))
    else:
        max_val = sorted(candidates)[-1]
        for i in range(len(candidates) - 1, -1, -1):
            if candidates[i] == max_val:
                del candidates[i]
                yield from map(" ".join, solve(n - 1, s, r))
                candidates.insert(i, max_val)

if __name__ == "__main__":
    for _ in range(int(sys.argv[1]) or 1):
        n, s, r = map(int, sys.stdin.readline().strip().split())
        print("\n".join(" ".join(str(_) for _ in solutions) for solutions in solve(n, s + r, r)))
