def sortable_sequence(seq):
    counter = collections.Counter(seq)
    groups = {}
    available = set(range(1, max(seq)+1))

    def backtrack(start=0):
        for i in range(start, len(seq)):
            c = counter[seq[i]]
            if not groups.get(seq[i], False) and c > 1:
                # If element is repeated more than once, repeat it in sorted sequence
                backtrack(i+1)
                available.discard(seq[i])
                for j in range(c):
                    groups[seq[i]] = True
                    sorted_seq.append(seq[i])
            if not available:
                return

            for k in range(min(available), seq[i] + 1, 1):
                if k in groups or k not in available:
                    continue
                groups[k] = True
                sorted_seq.append(k)
                backtrack(i+1)
                available.remove(k)
            if seq[i+1] and seq[i]+1 == seq[i+1]:
                # If consecutive elements are the same, skip it in sorting
                backtrack(i+2)

    sorted_seq = []
    backtrack()

    return sorted_seq

def is_ugly(arr):
    for i in range(1, len(arr)):
        if arr[i] <= sum(arr[:i]):
            return True
    return False
