import sys
from numpy import zeros, identity, min

def solve():
    n = int(sys.stdin.readline())
    a, b = map(int, sys.stdin.readline().split())
    match_scores = [list(map(int, sys.stdin.readline().split())) for _ in range(n)]

    # Floyd-Warshall algorithm
    inf = float('inf')
    dp = zeros((n+1, n+1), dtype=int)
    for i in range(1, n+1):
        dp[i][i] = 0

    for x, y, score in match_scores:
        dp[x][y] = max(dp[x][y], score - min(x, y))
        dp[y][x] = max(dp[y][x], score - min(x, y))

    for k in range(1, n+1):
        for i in range(1, n+1):
            for j in range(1, n+1):
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j])

    d = sum([b - i for i in dp[1:, 0].sum(0) if i <= b]) // 2

    # Generate the match scores with the minimum number of draws
    for i in range(n):
        if dp[i+1][0] <= d + b%2:
            yield f'{i+1}:0'
        else:
            break

    for i in range(1, n+1):
        for j in range(i+1, n+1):
            if dp[i][j] <= d:
                goal_a = (dp[i][j] + min(i, j)) // 2
                goal_b = (dp[i][j] - min(i, j)) // 2
                goal_c = max(0, (dp[i+1][0] - dp[i][j]) * 2)
                yield f'{goal_a}:{goal_b}' if goal_c % 2 == d%2 else None
                break

    # Generate the remaining matches with conceded goals equal to the number of required draws
    for i in range(n):
        if dp[i+1][0] > d + b%2:
            yield f'{d-b}:{b}'

if __name__ == '__main__':
    print(*solve())
