import itertools

def validate_board(n, positions):
    visited = set()
    for position in positions:
        x, y = position
        if (x, y) in visited or (y, x) in visited:
            return False
        visited.add((x, y))
        if n <= x + 1 and any(abs(i - x) == abs(j - y) for i, j in positions if (i, j) != (x, y)):
            return False
    return True

def is_valid_move(n, positions, start, end):
    for position in positions:
        if start[0] == position[0] or start[1] == position[1]:
            continue
        if (abs(position[0] - start[0]) <= n and abs(position[1] - start[1]) <= n) and (abs(position[0] - end[0]) <= n and abs(position[1] - end[1]) <= n):
            return False
    return not any((abs(i - j) == abs(k - l) for i, j, k, l in itertools.product(start, end, positions[:-1], positions)))

def solve():
