def solve():
    tests = int(input().strip())
    for _ in range(tests):
        n = int(input().strip())
        a = list(map(int, input().split()))
        operations = 0

        # Create graph where vertices represent array indices and edges
        # have weight of -1. A self-edge represents unreachability from that index.
        graph = [{} for _ in range(n)]
        for i in range(1, n):
            if a[i] > a[i - 1]:
                # An edge exists if the current element is greater than the previous one
                graph[i][i - 1] = {'weight': -1}
            else:
               # Add self-edge as unreachable
                graph[i][i] = {'weight': None}

        visited = [False]*n
        q = deque()

        # DFS to find sinks (elements not reachable from smaller indices) and perform operations on them
        for i in range(n):
            if not visited[i]:
                q.append((i, []))
                visited[i] = True
                while q:
                    index, path = q.pop()
                    for node in list(graph[index].keys()):
                        if graph[node][index]['weight'] == -1 and not visited[node]:
                            q.append((node, path + [index]))
                            visited[node] = True
                operations += len(path) - 1

        print(operations)
