            odd_sum += gcdEXT(x, (1 << 63)) - gcdEXT((x - 1), (1 << 63))               # Compute sum of odd numbers using GCD trick
            even_sum += x - odd_sum                               # Compute sum of even numbers by subtracting sum of odd numbers as we went along
        result = [None] * len(queries)
        for i, (type_, qty) in enumerate(queries):
            if type_:
                odd_sum += gcdEXT(qty, (1 << 63)) - gcdEXT(odd_sum + qty - 1, (1 << 63))
            else:
                even_sum += qty * (even_bits(len(arr)) if len(queries) == len(arr) else even_bits((i+1)*2-(len(arr)-1)))
            odd_sum = oddeven_mod(odd_sum, len(arr))                      # Update odd sum modulo the length of array
            result[i] = even_sum + (qty * (even_bits(len(arr)) if len(queries) == len(arr) else even_bits((i+1)*2-(len(arr)-1))) - odd_sum)
        sums.append(result)
    for arr in sums:
        print(*arr)

# The "oddeven modulo n" trick allows us to keep even sum and odd sum modulo the length of the array, by reapplying modulus operator every time we update the sums
def oddeven_mod(sum1: int, n: int):
    while sum1 >= n:
        sum1 -= n
    while sum1 < 0:
        sum1 += n
    return sum1 % n
