    for s in subsegments:
        subsegments_count[s] += 1
    subset_perms = {k: v for k, v in subsegments_count.items() if v == n-1}

    # construct connected set of permutation subsegments and find minimal spanning tree edges (MST) with minimum degree constraint 2
    graph = {subset: [subset|other for other in subset_perms if len(subset&other)>0] for subset in subset_perms}
    visited = set()
    mst = []
    def dfs(current_subset):
