def extend_and_merge(hours, mins, width):
    # Extend hours and mins lists until they have the same length as width.
    # Fill extended parts with 0s.
    hours = [0] * (len(width) - len(hours)) + hours
    mins = [0] * (len(width) - len(mins)) + mins

    # Merge hours, mins and width into a dictionary representing the height of each position.
    height_dict = defaultdict(int)
    for h, w in zip((hours + [0]) * 2, (width + [0]) * 2):
        if h >= w:
            key = f"h{h}", f"v{w}"
            height_dict[key] += 1
        else:
            key = f"h{h}", f"v{-w}"
            height_dict[key] -= 1
    max_height = max(height_dict.values())

    # Calculate the new perimeter, subtracting the areas of overlapping cells
    # (using the maximum height minus the height of each cell).
    perim = sum([2 * w for w in width]) + 4 * max_height
    for _, h in height_dict.items():
        if h != max_height:
            perim -= 2

    return perim

def solve(n_slabs, slab_sizes):
    # Calculate the gcd (greatest common divisor) of all given dimensions
    gcd = slab_sizes[0][0]
    for a, b in slab_sizes:
        gcd = gcd * abs(slab_sizes[0][1] // gcd) * abs(slab_sizes[-1][1] // gcd)

    if gcd > 1 or (gcd == 1 and len(set([a // gcd for a, b in slab_sizes])) != 1):
        return "Cannot arrange the given cheese slices."

    # Rotate all slabs so their shorter sides have a length of 1.
    # For simplicity, we assume that rotations are supported by changing signs of the x or y dimensions.
    # If any two slab sizes differ by more than one dimension, we can't make this assumption,
    # but it doesn't matter in this case since rotating the larger piece will result in a gap between pieces.
    rotated_slabs = []

    def add_rotated(a, b):
        if a >= b:
            rotated_slabs.append((min(a, b), max(a, b)))
        else:
            a, b = b, a
            rotated_slabs.append((max(a, b), min(a, b)))

    for (a, b) in slab_sizes:
        if a % gcd == 0 and b % gcd == 1:
            add_rotated(-b // gcd, a // gcd)
        elif a % gcd == 1 and b % gcd == 0:
            add_rotated(a // gcd, -b // gcd)
        else:
            rotated_slabs.append((a, b))

    # Sort the rotated slabs in ascending order of heights and widths.
    # This is only required if we have assumed that rotations are supported by changing signs of dimensions.
    rotated_slabs = sorted(rotated_slabs, key=lambda a, b: -a - abs(b))

    # Merge slabs into a list where each element consists of the merged height-width pair and its length.
    slab_heights_and_widths = [None] * gcd
    for h, w in rotated_slabs:
        if slab_heights_and_widths[-w - 1] is None:
            slab_heights_and_widths[-w - 1] = (h, w + 1)
        else:
            if h != slab_heights_and_widths[-w - 1][0]:
                return "Cannot arrange the given cheese slices."
            slab_heights_and_widths[-w - 1] = (slab_heights_and_widths[-w - 1][0], slab_heights_and_widths[-w - 1][1] + w + 1)

    # Extend the merged heights and widths until they have sufficient length.
    slab_heights = [None] * len(rotated_slabs)
    slab_widths = [None] * len(rotated_slabs)
    for idx in range(len(rotated_slabs)):
        slab_heights[idx], slab_widths[idx] = slab_heights_and_widths[rotated_slabs[idx][1]]
    for h, w in [[slab_heights[i:j], slab_widths[i:j]] for i, j in zip(range(len(rotated_slabs)), range(1, len(rotated_slabs) + 1))]:
        if len(h) > 1 or len(w) > 1:
            h = [h[0]] * len(w)
            w = w * len(h)
        slab_heights[:len(h)] = h[::-1] + h
        slab_widths[:len(w)] = w

    return extend_and_calculate(n_slabs, slab_heights, slab_widths, gcd)

def extend_and_calculate(n, heights, widths, gcd):
    extended_heights = [[None] * (gcd - h[0][0]) for h in heights]
    for idx, h in enumerate(heights):
        if h:
