    # Return any cell if no isolated cell found.
    return sorted(list(itertools.product(range(1, n + 1), range(1, m + 1))))[0]

def compositions(iterable, r=2):
    "Generate every composition of r elements in iterable"
    pool = tuple(iterable)
    if len(pool) == 0:
        return []
    else:
        a = [pool[i:]] + [pool[:i] for i in range(1, len(pool))]
        # filter out any compositions containing duplicated elements
        return functools.reduce(lambda a, b: [ab for ab in axt(a) for a in b], a, [[]])

def axt(a):
