        combo_gen = filter(None, map(combinations, itertools.product([i for i in range(1, 1000000)], repeat=N)))

        # Keep track of the minimum number of operations required for each valid combination set
        min_ops_map = {frozenset({len(combo) for combo in c}): max(len(c), len(combo) - 1) for c in combo_gen if any(is_equilateral(c)}}

        # Iterate through the possible number of sticks, removing combinations that can no longer form an equilateral triangle after having a stick added or removed
        # until we reach the desired number of sticks
        for num_sticks in reversed(range(0, N + 1)):
            min_ops_map = {k: min(min_ops_map[k], v - num_sticks) for k, v in min_ops_map.items() if num_sticks <= len(k)}
            for combo_set, ops in list(min_ops_map.keys()):
                # For each valid combination set, generate and consider the number of operations required to form an equilateral triangle with one more or one less stick
                if max(len(combo) + 1 for combo in c) <= N:
                    min_ops_map[frozenset({len(combo) + 1 for combo in c})] = max(min_ops_map[frozenset({len(combo) + 1 for combo in c})], ops - 1)
                if max(len(combo) - 1 for combo in c) >= 2:
                    min_ops_map[frozenset({len(combo) - 1 for combo in c})] = max(min_ops_map[frozenset({len(combo) - 1 for combo in c})], ops + 1)

        # Return the minimum number of operations required to form an equilateral triangle with the desired number of sticks
        return min(min_ops_map.values())

