from math import inf
import sys

def solve(orbits, cost):
    n = len(orbits)
    min_cost = inf

    # Memoized table to store the minimum cost for each sub problem.
    memo = [0] * (n+1)

    # Initial base cases when no planets or just 1 planet are there.
    if n == 0:
        return 0
    elif n == 1:
        return orbits[0] * cost

    # Iterate through all the orbits and try to find the one with least cost to destroy using the second machine only.
    for i in range(n):
        if orbits[i] > 1:
            destroy_orbit = (orbits[i] - 1) * cost
            memo[orbits[i]] = min(memo[orbits[i]], destroy_orbit)
    # Now subtract the destroyed orbit's cost from all other planets to get the remaining minimum cost.
    for i in range(n):
        if orbits[i] > 1:
            memo[1] += min(memo[orbits[i]], (orbits[i] - 1) * cost)
    # Calculate the minimum cost where all planets have their own orbit using the first machine only.
    for i in range(1, n+1):
        memo[i] += orbits[0]

    # Find the smallest between memoization table and the case of destroying the smallest orbit using first machine,
    # as it is not covered by memoization above (smallest orbit has only 1 planet).
    for i in range(1, n+1):
        min_cost = min(min_cost, memo[i] + orbits[0])
    return min_cost

