            new_perm = list(cur_perm)
            new_perm[i], new_perm[i+1] = new_perm[i+1], new_perm[i]

            # calculate the score of the new permutation by iterating through its elements and updating x based on current position
            next_score = 0
            for j in range(len(new_perm)):
