from numpy import *
def solve(N, M):
    grid = arange(1, (M + 1) * N).reshape((N, M))
    dominoes = zeros((N, M), dtype=bool)

    for y in range(2, N+1):
        for x in range(y-1, M+1, y - 1):
            if dominoes[y-1][x]: continue
            domino_start = grid[y-1, x] + 1
            domino_end = min((grid[y-1, x + y-1]) % (M+1), grid[y, x])

            if domino_end - domino_start == 1:
                dominoes[y-1][x] = True
                dominoes[y][x + y - 1] = True

    return sum(sum(dominoes[i, :]) for i in range(N))
