import itertools
import sys

def solve(n, k):
    def _solve(a, b, rem):
        # Base case: if we have reached n/2 pairs, return True
        if a == n // 2:
            return True
        # Iterate over possible next pairs. If a valid pair is found, continue recursion
        for pair in (_solve(a + 1, b, (4 * rem)) if rem % 4 == 0 else itertools.permutations((a + 1, b))):
            remaining_pair = pair if rem % 4 == 0 else (b, a)
            value = (a + k) * b
            if value % 4 == 0:
                yield from _solve(*remaining_pair, value // 4)
        return False
    # Initialize recursion using the first pair and (n-1)/2 remaining pairs
    for pair in itertools.permutations((1, n // 2)):
        if _solve(*pair, k * n // 4).__next__():
            break
    else:
        return 'NO'

    # If we reach this point, we have a solution
    output = []
    for pair in _solve(1, n//2, k*n//4):
        output.append(' '.join(str(x) for x in pair))
    print('YES')
    print('\n'.join(output))

