import sys
from heapq import heappush, heappop

def manhattan_distance(cur, next):
    return abs(next[0] - cur[0]) + abs(next[1] - cur[1])

def neighbors(board, pos=[0, 0]):
    moves = [(pos[0], pos[1] + step) for step in range(1, len(board[0]) * 2 // 3 + 1)] +\
            [(pos[0] + step, pos[1]) for step in range(1, len(board) * 2 // 3 + 1)]
    return filter(lambda p: 0 <= p[0] < len(board) and 0 <= p[1] < len(board[0]), moves)

def win_condition(board, pos):
    for i in range(pos[0], len(board)):
        if board[i][pos[1]] == 0:
            break
        if board[i][pos[1]] != -1:
            return False

    for j in range(pos[1], len(board[0])):
        if board[pos[0]][j] == 0:
            break
        if board[pos[0]][j] != -1:
            return False
    return True

def solve():
    n, m = map(int, sys.stdin.readline().split())
    if n * m < 6:
        winner = 'Tonya' if n * m % 2 else 'Burenka'
    else:
        board = [[-1] * m for _ in range(n)]
        board[0][0] = 0
        frontier = [(manhattan_distance((0, 0), p), p, (0, 0)) for p in neighbors(board)]
        heappush((frontier), (0, (0, 0), (1, 0)))
        while frontier:
            dist, pos, parents = heappop(frontier)
            if win_condition(board, pos):
                winner = 'Burenka'
                break
            board[pos[0]][pos[1]] = 0

            for neighbor in neighbors(board, pos):
                heappush((frontier), (manhattan_distance(pos, neighbor), neighbor, parents))
        else:
            winner = 'Tonya'
    print(winner)

if __name__ == "__main__":
    for _ in range(int(sys.stdin.readline())):
        solve()
