    def distance(x, y):
        return [x, y] if x == 0 or y == 0 else [[-1, 0], [1, 0], [], []]

    def neighbors(v):
        dirs = [[v[0] - 1, v[1]], [v[0] + 1, v[1]], [v[0], v[1] + 1], [v[0], v[1] - 1]]
        ns = []
