                    [[0, -1] for i in range(m) if not grid[0][i]]
        heapq.heapify(non_boxes)
        dist = defaultdict(lambda x: inf)
        dist[(0, 0)] = 0
        prev = {}

        while non_boxes:
            u = heapq.heappop(non_boxes)
            if u[0] == -1 or u[1] == -1:
                continue

            for d, d_weight in neighbors(u):
                v = (d[0], d[1])
                w = dist[u] + d_weight
                if w < dist[v]:
