import sys
import math

def extended_euclidean(a, b):
    if (b == 0):
        return (1, 0, a) if a > 0 else (0, 1, -a)
    x1, x2, y1, y2 = extended_euclidean(b, a % b)
    return (y2, x2 - y2 * (a // b), x1 - y1 * (a // b))

def solve(n):
    max_cost, best_d, best_perm = 0, 0, [None] + list(range(1, n+1))

    def permutation_cost(arr, d):
        nonlocal max_cost
        if len(arr) == n:
            cost = sum(i * d for i in zip(arr[:-1], arr[1:]) if i * d == arr[i+1])
            max_cost = max(max_cost, cost)
            return
        gcd_remainder = list(extended_euclidean(d, n - arr[-1]))[2]
        for div in range(gcd_remainder + 1, d - gcd_remainder - 1, -gcd_remainder):
            permutation_cost(arr[::-1] + [arr[-1] * (d // div) + div], div)

    permutation_cost([0], math.inf)
    for d in range(1, int(math.sqrt(max_cost))):
        if max_cost % d == 0:
            c = max_cost // d
            if c * d == max_cost:
                best_d = d
                break
    best_perm = best_perm[::-1]
    return best_d, best_perm

def main():
