import functools

def solve(matrix):
    m, n = len(matrix), len(matrix[0])

    @functools.lru_cache((m, n), 1)
    def dp(i, j, marked=False):
        if not (0 <= i < m and 0 <= j < n):
            return float('inf')
        if matrix[i][j] == 0:
            return 0 if marked else 1
        nonlocal cnt
        cnt += 1
        result = dp(i, j, True) + 1
        for k in range(m):
            result = min(result, dp(k, j, False) + cnt * (k != i))
        for k in range(n):
            result = min(result, dp(i, k, False) + cnt * (k != j))
        return result

    cnt = 0
    return dp(0, 0)

def main():
