from itertools import product, chain
from functools import reduce

def solve(arr):
    m = len(arr)
    n = len(arr[0])
    graph = [[[] for _ in range(n)] for _ in range(m)]
    grass_count = 0
    for i, row in enumerate(arr):
        for j, val in enumerate(row):
            if val == 1:
                grass_count += 1
            if j > 0 and arr[i][j-1] == 1:
                graph[i][j].append((j-1, i))
            if j < n-1 and arr[i][j+1] == 1:
                graph[i][j].append((j+1, i))
            if i > 0 and arr[i-1][j] == 1:
                graph[i][j].append((j, i-1))
            if i < m-1 and arr[i+1][j] == 1:
                graph[i][j].append((j, i+1))
    visited = [[False]*n for _ in range(m)]

    def dfs(row, col):
        visited[row][col] = True
        if arr[row][col] == 1:
            grass_count -= 1
        for (nr, nc) in graph[row][col]:
            if not visited[nr][nc]:
                dfs(nr, nc)
    for i, row in enumerate(arr):
        for j, _ in enumerate(row):
            if not visited[i][j]:
                dfs(i, j)

    if grass_count > 0:
        power = 1
        while grass_count > 1:
            new_arr = [[0]*n for _ in range(m)]
            for r, c in product(range(m), range(n)):
                cells = [(r + (ri - r) % m, c + (ci - c) % n) for ri, ci in graph[r][c]]
                if len(cells) > 1:
                    neighbour_sum = sum(arr[c][ri] for ri, ci in cells if arr[ri][ci])
                    new_arr[r][c] = int(neighbour_sum <= power and grass_count > 0)
            arr = new_arr
            power *= 2
    return power // 2

def main():
    cases = int(input().strip())
    for _ in range(cases):
        arr = [list(map(int, input().split())) for _ in range(2)]
        print(solve(arr))

if __name__ == '__main__':
    main()
