from heapq import heappush, heappop

def dijkstra(grid: list, start: tuple, end: tuple):
    cost = 0
    dist = {}
    prev = {}
    min_heap = []

    for i in range(1, len(grid) + 1):
        for j in range(1, len(grid[0]) + 1):
            key = (i - 1) * len(grid[0]) + j
            dist[key] = float('inf')
            prev[key] = None
            if i == 1 and j == 1:
                cost += grid[i - 1][j - 1]
                dist[(i - 1) * len(grid[0]) + j], prev = cost, (i, j)
            heappush(min_heap, (cost + grid[i - 1][j - 1], key))

    while min_heap:
        cost, current = heappop(min_heap)

        if cost > dist[(current // len(grid[0])) * len(grid[0]) + current % len(grid[0])]:
            continue

        for i, j in ((current + 1, (current // len(grid[0])) * len(grid[0]) + current % len(grid[0])),
                     (current, (current // len(grid[0])) * len(grid[0]) + current % len(grid[0]) + 1)):
            if i not in range(1, len(grid) + 1) or j not in range(1, len(grid[0]) + 1):
                continue

            key = (i - 1) * len(grid[0]) + j
            if dist[key] > cost + grid[i - 1][j - 1]:
                dist[key], prev[key] = cost + grid[i - 1][j - 1], current
                heappush(min_heap, (cost + grid[i - 1][j - 1], key))

