import heapq

def bfs(graph, start, end):
    queue = [(start[0], *start[1])]
    cost = 0

    visited = set()
    visited.add((*start))

    while queue:
        cost, (i, j) = queue.pop(0)

        if (i, j) == end:
            return cost

        for next in graph[(i, j)]:
            if next not in visited:
                heapq.heappush(queue, (cost + next[1], *next[0]))
                visited.add(next)

    return -1

def solve():
    t = int(input())

    for _ in range(t):
        n, m = map(int, input().split())

        a = {}
        graph = {}

        for i in range(1, n + 1):
            for j in range(1, m + 1):
                key = (i, j)
                val = (i - 1) * m + j
                a[key] = val
                graph[(i, j)] = [((i + 1, j), a[(i + 1, j)]) if (i + 1 <= n) else [], ((i, j + 1), a[(i, j + 1)]) if (j + 1 <= m) else []]

        print(bfs((n, m), (1, 1), graph))
